(function(){
  const colors={cyan:'#74e5d0',orange:'#ffb55b',violet:'#b49cff',lime:'#c9f35b',line:'#53625c',dark:'#0b1112'};
  const labels={slider:['旋转输入','往复直线'],eccentric:['偏心旋转','短距往复'],cam:['轮廓旋转','按规律升降'],rack:['齿轮旋转','齿条直线'],geneva:['连续旋转','间歇转位'],screw:['螺杆旋转','直线升降'],ratchet:['往复摆动','单向间歇'],belt:['主动轮旋转','远距旋转'],fourbar:['曲柄旋转','摇杆摆动'],worm:['蜗杆旋转','垂直轴减速']};
  function defs(){return `<defs><filter id="glow"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter><pattern id="teeth" width="12" height="8" patternUnits="userSpaceOnUse"><path d="M0 7V2h7v5" fill="none" stroke="${colors.lime}" stroke-width="3"/></pattern></defs>`}
  function frame(type,body,small=false){const l=labels[type]||['输入','输出'];return `<svg class="kinematic-svg ${small?'preview-svg':''}" viewBox="0 0 520 300" aria-label="${l[0]}转换为${l[1]}的运动简图">${defs()}<g class="grid-lines"><path d="M30 255H490M45 30V270"/></g>${body}<g class="motion-caption"><text x="32" y="24">输入 · ${l[0]}</text><text x="348" y="24">输出 · ${l[1]}</text></g></svg>`}
  function diagram(type,small=false){
    const axle=`<circle cx="150" cy="155" r="8" class="joint fixed"/><circle cx="150" cy="155" r="68" class="outline"/>`;
    if(type==='slider'||type==='eccentric'||type==='cam') return frame(type,`${axle}<g data-rotor><path d="M150 155L208 178" class="link orange"/><circle data-drive cx="208" cy="178" r="13" class="drive"/></g><path data-rod d="M208 178L355 155" class="link lime"/><g data-slider><rect x="340" y="122" width="70" height="66" rx="7" class="slider"/><circle cx="355" cy="155" r="8" class="joint"/></g><path d="M315 111H450M315 199H450" class="guide"/>`,small);
    if(type==='rack') return frame(type,`<g data-rotor><circle cx="175" cy="150" r="62" class="gear"/><path d="M175 150L223 170" class="link orange"/><circle data-drive cx="223" cy="170" r="13" class="drive"/></g><g data-rack><rect x="235" y="185" width="220" height="38" rx="4" class="rack"/><path d="M242 185h205" class="rack-teeth"/></g><path d="M230 236H470" class="guide"/>`,small);
    if(type==='geneva') return frame(type,`<g data-rotor><circle cx="150" cy="155" r="64" class="outline"/><path d="M150 155L205 155" class="link orange"/><circle data-drive cx="205" cy="155" r="13" class="drive"/></g><g data-output><circle cx="345" cy="155" r="78" class="geneva"/><path d="M345 82v48M345 180v48M272 155h48M370 155h48" class="slot"/><circle cx="345" cy="155" r="10" class="joint fixed"/></g>`,small);
    if(type==='screw') return frame(type,`<g data-screw><rect x="75" y="137" width="330" height="36" rx="18" class="screw"/><path d="M90 168l22-27m5 27l22-27m5 27l22-27m5 27l22-27m5 27l22-27m5 27l22-27m5 27l22-27m5 27l22-27m5 27l22-27" class="thread"/><circle data-drive cx="82" cy="155" r="14" class="drive"/></g><g data-nut><rect x="300" y="104" width="78" height="102" rx="8" class="nut"/><circle cx="339" cy="155" r="22" class="nut-hole"/></g>`,small);
    if(type==='ratchet') return frame(type,`<g data-output><circle cx="270" cy="155" r="80" class="ratchet"/><path d="M270 75l9 18 20-7 3 22 21 2-8 20 18 12-16 15 13 18-20 8 4 21-22-2-5 21-18-12-14 17-12-19-20 9-2-22-22 1 7-21-18-11 16-16-13-18 21-7-4-22 22 3 6-21 18 13 15-17 11 19z" class="ratchet-teeth"/><circle cx="270" cy="155" r="13" class="joint fixed"/></g><g data-pawl><path d="M105 92L214 134L198 158L99 126z" class="pawl"/><circle data-drive cx="105" cy="109" r="13" class="drive"/></g>`,small);
    if(type==='belt') return frame(type,`<g data-left><circle cx="150" cy="155" r="66" class="pulley"/><path d="M150 155L198 155" class="link orange"/><circle data-drive cx="198" cy="155" r="13" class="drive"/></g><g data-right><circle cx="385" cy="155" r="48" class="pulley"/></g><path data-belt d="M150 89H385A48 48 0 0 1 385 203H150A66 66 0 0 1 150 89" class="belt-path"/>`,small);
    if(type==='fourbar') return frame(type,`<path d="M110 224H416" class="ground"/><circle cx="145" cy="224" r="9" class="joint fixed"/><circle cx="388" cy="224" r="9" class="joint fixed"/><g data-crank><path d="M145 224L205 154" class="link orange"/><circle data-drive cx="205" cy="154" r="13" class="drive"/></g><path data-coupler d="M205 154L345 145" class="link lime"/><path data-rocker d="M345 145L388 224" class="link violet"/><circle cx="345" cy="145" r="9" class="joint"/>`,small);
    return frame('worm',`<g data-worm><rect x="75" y="127" width="245" height="56" rx="25" class="worm"/><path d="M92 175l34-42m6 42l34-42m6 42l34-42m6 42l34-42m6 42l34-42" class="thread"/><circle data-drive cx="87" cy="155" r="13" class="drive"/></g><g data-output><circle cx="376" cy="155" r="73" class="gear"/><circle cx="376" cy="155" r="16" class="joint fixed"/></g>`,small);
  }
  function mount(container,type){
    container.innerHTML=diagram(type,false);const svg=container.querySelector('svg');let angle=0,viewX=4,viewY=-4,driving=false,viewing=false,last={x:0,y:0};
    function update(a){angle=a;const rad=a*Math.PI/180,s=Math.sin(rad),c=Math.cos(rad);const rotor=svg.querySelector('[data-rotor], [data-left], [data-crank], [data-screw], [data-worm]');if(rotor)rotor.setAttribute('transform',`rotate(${a} ${type==='fourbar'?145:type==='belt'?150:type==='screw'||type==='worm'?82:150} ${type==='fourbar'?224:155})`);
      if(['slider','eccentric','cam'].includes(type)){const x=150+58*c,y=155+58*s,out=355+44*c;svg.querySelector('[data-rod]').setAttribute('d',`M${x} ${y}L${out} 155`);svg.querySelector('[data-slider]').setAttribute('transform',`translate(${out-355} 0)`)}
      if(type==='rack')svg.querySelector('[data-rack]').setAttribute('transform',`translate(${34*s} 0)`);
      if(type==='geneva')svg.querySelector('[data-output]').setAttribute('transform',`rotate(${Math.floor((a+22.5)/90)*90} 345 155)`);
      if(type==='screw')svg.querySelector('[data-nut]').setAttribute('transform',`translate(${95*(a%360)/360-45} 0)`);
      if(type==='ratchet'){svg.querySelector('[data-output]').setAttribute('transform',`rotate(${Math.floor(a/30)*30} 270 155)`);svg.querySelector('[data-pawl]').setAttribute('transform',`rotate(${12*s} 105 109)`)}
      if(type==='belt'){svg.querySelector('[data-right]').setAttribute('transform',`rotate(${a*1.35} 385 155)`);svg.querySelector('[data-belt]').style.strokeDashoffset=String(-a/2)}
      if(type==='fourbar'){const x=145+92*c,y=224+92*s,rx=388-70*Math.cos(rad*.55),ry=224-70*Math.sin(rad*.55);svg.querySelector('[data-coupler]').setAttribute('d',`M${x} ${y}L${rx} ${ry}`);svg.querySelector('[data-rocker]').setAttribute('d',`M${rx} ${ry}L388 224`)}
      if(type==='worm')svg.querySelector('[data-output]').setAttribute('transform',`rotate(${-a/4} 376 155)`);
    }
    function rotateView(){container.style.transform=`perspective(900px) rotateX(${viewX}deg) rotateY(${viewY}deg)`}
    svg.addEventListener('pointerdown',e=>{last={x:e.clientX,y:e.clientY};driving=!!e.target.closest('[data-drive]');viewing=!driving;svg.setPointerCapture(e.pointerId)});
    svg.addEventListener('pointermove',e=>{if(driving){const r=svg.getBoundingClientRect(),cx=r.left+r.width*.29,cy=r.top+r.height*.52;angle=Math.atan2(e.clientY-cy,e.clientX-cx)*180/Math.PI;update(angle)}else if(viewing){viewY+=(e.clientX-last.x)*.12;viewX-=(e.clientY-last.y)*.1;viewX=Math.max(-18,Math.min(18,viewX));viewY=Math.max(-24,Math.min(24,viewY));last={x:e.clientX,y:e.clientY};rotateView()}});
    svg.addEventListener('pointerup',()=>{driving=false;viewing=false});update(0);rotateView();return{update};
  }
  window.MechanicsV2={preview:type=>diagram(type,true),mount,labels};
})();
